"""E-commerce API routes -- Generated by APIForge example.

Demonstrates the output quality of APIForge for a real-world API.
"""
from __future__ import annotations

import uuid
from datetime import datetime
from typing import Any

from fastapi import APIRouter, Depends, HTTPException, Query
from pydantic import BaseModel

router = APIRouter(prefix="/api/v1")


# ─── Models ──────────────────────────────────────────────────────


class ProductCreate(BaseModel):
    name: str
    description: str = ""
    price: float
    category: str
    stock: int = 0
    tags: list[str] = []


class ProductResponse(BaseModel):
    id: str
    name: str
    description: str
    price: float
    category: str
    stock: int
    tags: list[str]
    created_at: str
    updated_at: str


class CartItem(BaseModel):
    product_id: str
    quantity: int


class CartResponse(BaseModel):
    id: str
    items: list[dict[str, Any]]
    total: float
    created_at: str


class OrderCreate(BaseModel):
    shipping_address: str
    payment_method: str = "card"


class OrderResponse(BaseModel):
    id: str
    user_id: str
    items: list[dict[str, Any]]
    total: float
    status: str
    shipping_address: str
    created_at: str


# ─── In-memory stores (for demo) ─────────────────────────────────

_products: dict[str, dict] = {}
_carts: dict[str, dict] = {}
_orders: dict[str, dict] = {}


# ─── Product endpoints ───────────────────────────────────────────


@router.get("/products", tags=["products"])
async def list_products(
    category: str | None = Query(None, description="Filter by category"),
    min_price: float | None = Query(None, description="Minimum price"),
    max_price: float | None = Query(None, description="Maximum price"),
    search: str | None = Query(None, description="Search by name"),
    page: int = Query(1, ge=1, description="Page number"),
    per_page: int = Query(20, ge=1, le=100, description="Items per page"),
):
    """List products with filtering, search, and pagination."""
    items = list(_products.values())
    if category:
        items = [p for p in items if p["category"] == category]
    if min_price is not None:
        items = [p for p in items if p["price"] >= min_price]
    if max_price is not None:
        items = [p for p in items if p["price"] <= max_price]
    if search:
        items = [p for p in items if search.lower() in p["name"].lower()]
    total = len(items)
    start = (page - 1) * per_page
    items = items[start : start + per_page]
    return {"items": items, "total": total, "page": page, "per_page": per_page}


@router.post("/products", tags=["products"], status_code=201)
async def create_product(body: ProductCreate):
    """Create a new product."""
    product_id = str(uuid.uuid4())[:8]
    now = datetime.utcnow().isoformat()
    product = {
        "id": product_id,
        "name": body.name,
        "description": body.description,
        "price": body.price,
        "category": body.category,
        "stock": body.stock,
        "tags": body.tags,
        "created_at": now,
        "updated_at": now,
    }
    _products[product_id] = product
    return product


@router.get("/products/{product_id}", tags=["products"])
async def get_product(product_id: str):
    """Get a product by ID."""
    if product_id not in _products:
        raise HTTPException(status_code=404, detail="Product not found")
    return _products[product_id]


@router.put("/products/{product_id}", tags=["products"])
async def update_product(product_id: str, body: ProductCreate):
    """Update an existing product."""
    if product_id not in _products:
        raise HTTPException(status_code=404, detail="Product not found")
    product = _products[product_id]
    product.update(body.model_dump())
    product["updated_at"] = datetime.utcnow().isoformat()
    return product


@router.delete("/products/{product_id}", tags=["products"])
async def delete_product(product_id: str):
    """Delete a product."""
    if product_id not in _products:
        raise HTTPException(status_code=404, detail="Product not found")
    del _products[product_id]
    return {"deleted": product_id}


# ─── Cart endpoints ──────────────────────────────────────────────


@router.get("/cart/{user_id}", tags=["cart"])
async def get_cart(user_id: str):
    """Get the user's shopping cart."""
    if user_id not in _carts:
        _carts[user_id] = {"id": user_id, "items": [], "total": 0.0, "created_at": datetime.utcnow().isoformat()}
    return _carts[user_id]


@router.post("/cart/{user_id}/items", tags=["cart"])
async def add_to_cart(user_id: str, item: CartItem):
    """Add an item to the cart."""
    if item.product_id not in _products:
        raise HTTPException(status_code=404, detail="Product not found")
    if user_id not in _carts:
        _carts[user_id] = {"id": user_id, "items": [], "total": 0.0, "created_at": datetime.utcnow().isoformat()}
    cart = _carts[user_id]
    product = _products[item.product_id]
    cart["items"].append({
        "product_id": item.product_id,
        "name": product["name"],
        "price": product["price"],
        "quantity": item.quantity,
    })
    cart["total"] = sum(i["price"] * i["quantity"] for i in cart["items"])
    return cart


@router.delete("/cart/{user_id}/items/{product_id}", tags=["cart"])
async def remove_from_cart(user_id: str, product_id: str):
    """Remove an item from the cart."""
    if user_id not in _carts:
        raise HTTPException(status_code=404, detail="Cart not found")
    cart = _carts[user_id]
    cart["items"] = [i for i in cart["items"] if i["product_id"] != product_id]
    cart["total"] = sum(i["price"] * i["quantity"] for i in cart["items"])
    return cart


# ─── Order endpoints ─────────────────────────────────────────────


@router.post("/orders/{user_id}", tags=["orders"], status_code=201)
async def create_order(user_id: str, body: OrderCreate):
    """Create an order from the user's cart."""
    if user_id not in _carts or not _carts[user_id]["items"]:
        raise HTTPException(status_code=400, detail="Cart is empty")
    cart = _carts[user_id]
    order_id = str(uuid.uuid4())[:8]
    order = {
        "id": order_id,
        "user_id": user_id,
        "items": cart["items"],
        "total": cart["total"],
        "status": "pending",
        "shipping_address": body.shipping_address,
        "payment_method": body.payment_method,
        "created_at": datetime.utcnow().isoformat(),
    }
    _orders[order_id] = order
    _carts[user_id] = {"id": user_id, "items": [], "total": 0.0, "created_at": datetime.utcnow().isoformat()}
    return order


@router.get("/orders/{user_id}", tags=["orders"])
async def list_orders(user_id: str):
    """List all orders for a user."""
    user_orders = [o for o in _orders.values() if o["user_id"] == user_id]
    return {"items": user_orders, "total": len(user_orders)}


@router.get("/orders/{user_id}/{order_id}", tags=["orders"])
async def get_order(user_id: str, order_id: str):
    """Get a specific order."""
    if order_id not in _orders or _orders[order_id]["user_id"] != user_id:
        raise HTTPException(status_code=404, detail="Order not found")
    return _orders[order_id]


@router.patch("/orders/{user_id}/{order_id}/status", tags=["orders"])
async def update_order_status(user_id: str, order_id: str, status: str = Query(...)):
    """Update order status."""
    if order_id not in _orders or _orders[order_id]["user_id"] != user_id:
        raise HTTPException(status_code=404, detail="Order not found")
    valid = ["pending", "confirmed", "shipped", "delivered", "cancelled"]
    if status not in valid:
        raise HTTPException(status_code=400, detail=f"Status must be one of: {valid}")
    _orders[order_id]["status"] = status
    return _orders[order_id]
